begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
insert into private.event_cover_config(singleton,operation_key_hash) values(true,encode(extensions.digest('synthetic-case-capability','sha256'),'hex')) on conflict(singleton) do update set operation_key_hash=excluded.operation_key_hash;
select set_config('request.headers','{"x-rollcall-cover-key":"synthetic-case-capability"}',true);
create temporary table casing_fixture as select gen_random_uuid() id,public.prepare_registration(' Ognjen3211 ','case@example.test','2000-02-29',repeat('a',64)) intent;
select is((select username from private.registration_intents where username='Ognjen3211'),'Ognjen3211','Trim whitespace and preserve exact validated spelling');
select is(public.prepare_registration('ognjen3211','other@example.test','2000-02-29',repeat('b',64))->>'status','duplicate','Lowercase collides with pending mixed-case identity');
select is(public.prepare_registration('OGNJEN3211','other@example.test','2000-02-29',repeat('b',64))->>'status','duplicate','Uppercase collides with pending mixed-case identity');
select throws_ok($$insert into private.registration_intents(username,email_hash,date_of_birth) values('OGNJEN3211',repeat('a',64),'2000-02-29')$$,'23505',null,'Database intent index independently enforces case-insensitive uniqueness');
insert into auth.users(id,email,raw_user_meta_data) select id,'case@example.test',jsonb_build_object('rollcall_registration_token',intent->>'token') from casing_fixture;
select is((select username from public.profiles where id=(select id from casing_fixture)),'Ognjen3211','Stored username retains casing');
select is((select display_name from public.profiles where id=(select id from casing_fixture)),'Ognjen3211','Initial display name retains casing');
select is(public.public_profile((select id from casing_fixture))->>'username','Ognjen3211','Public projection returns safe case-preserving username');
select ok(not(public.public_profile((select id from casing_fixture)) ?| array['email','dateOfBirth','birthYear','role']),'Public username projection adds no private fields');
select is(public.prepare_registration('ognjen3211','other@example.test','2000-02-29',repeat('c',64))->>'status','duplicate','Lowercase collides with saved mixed-case identity');
select is(public.prepare_registration('OGNJEN3211','other@example.test','2000-02-29',repeat('c',64))->>'status','duplicate','Uppercase collides with saved mixed-case identity');
create temporary table lowercase_fixture as select gen_random_uuid() id,public.prepare_registration('lower_player','lower@example.test','2000-02-29',repeat('e',64)) intent;
insert into auth.users(id,email,raw_user_meta_data) select id,'lower@example.test',jsonb_build_object('rollcall_registration_token',intent->>'token') from lowercase_fixture;
select is((select username from public.profiles where id=(select id from lowercase_fixture)),'lower_player','Lowercase registrations remain unchanged');
select throws_ok($$update public.profiles set username='OGNJEN3211' where id=(select id from lowercase_fixture)$$,'23505',null,'Existing profile index independently rejects case-insensitive duplicates');
-- Same-email retries may update a reservation spelling but cannot create two rows.
select public.prepare_registration('Retry_Name','retry@example.test','2000-02-29',repeat('d',64));
select public.prepare_registration('RETRY_NAME','retry@example.test','2000-02-29',repeat('d',64));
select is((select count(*)::int from private.registration_intents where lower(username)='retry_name'),1,'Same-email retry preserves one canonical reservation');
select is((select username from private.registration_intents where lower(username)='retry_name'),'RETRY_NAME','Latest validated spelling retained on same-email retry');
select is(has_column_privilege('authenticated','public.profiles','username','UPDATE'),false,'No new direct client username writes');
select ok(not (select prosecdef from pg_proc where oid='public.public_profile(uuid)'::regprocedure),'Public profile keeps caller RLS');
select is(has_table_privilege('authenticated','private.registration_intents','SELECT'),false,'Private reservation ACL unchanged');
select * from finish();
rollback;
